GO
SET QUOTED_IDENTIFIER OFF
GO
CREATE   PROCEDURE dbo.WH_PDA_PPT_TEST_RESET @Screen varchar(10)
AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON;
    DECLARE @S varchar(10)=LOWER(LTRIM(RTRIM(ISNULL(@Screen,''))));
    IF @S NOT IN('release','putaway','inventory','adjust','history') THROW 51700,'Unknown WH PPT test screen.',1;
    DECLARE @Rows table
    (
      LotNo nvarchar(100),
      ItemNo varchar(50),
      Qty decimal(18,3),
      LocationNo varchar(50),
      ReceivedAt datetime2
    );
    INSERT @Rows
    SELECT L.LotCode,L.ItemNo,COALESCE(NULLIF(L.BatchSize,0),NULLIF(L.RemainingQty,0),1),
      CASE
        WHEN L.LotCode='5011LL260908810001' THEN 'B0-10-A1'
        WHEN L.LotCode='5011LL260908810002' THEN 'B0-10-B1'
        WHEN L.LotCode='5011LL260908810003' THEN 'B0-09-D2'
        WHEN L.LotCode='5011LL260908810004' THEN 'B0-08-B1'
        WHEN L.LotCode IN('5011LL260908850001','5011LL260908850002','5011LL260908850003') THEN NULL
        WHEN L.LotCode='5011LL260908850004' THEN 'B0-10-A1'
        WHEN L.LotCode='5011LL260908820001' THEN 'B0-10-A1'
        WHEN L.LotCode='5011LL260908820002' THEN 'B0-10-B1'
        WHEN L.LotCode='5011LL260908820003' THEN 'B0-09-D2'
        WHEN L.LotCode='5011LL260908830001' THEN 'B0-12-B1'
        ELSE 'B0-08-C1' END,
      COALESCE(L.ProducedAt,SYSDATETIME())
    FROM dbo.tbl_Lot L
    WHERE (@S='release' AND L.LotCode LIKE '5011LL26090881%')
       OR (@S='putaway' AND L.LotCode LIKE '5011LL26090885%')
       OR (@S='inventory' AND L.LotCode LIKE '5011LL26090882%')
       OR (@S='adjust' AND L.LotCode LIKE '5011LL26090883%')
       OR (@S='history' AND L.LotCode LIKE '5011LL26090884%');
    IF (SELECT COUNT(*) FROM @Rows) <> CASE @S WHEN 'release' THEN 4 WHEN 'putaway' THEN 4 WHEN 'inventory' THEN 3 ELSE 1 END
        THROW 51702,'SCTEST1 WH data is missing. Apply PDA_SEED.sql first.',1;
    BEGIN TRANSACTION;
    DELETE T FROM dbo.WH_InventoryTransaction T JOIN @Rows R ON R.LotNo=T.LotNo COLLATE DATABASE_DEFAULT;
    MERGE dbo.WH_Inventory T USING(SELECT R.*,I.ItemName FROM @Rows R LEFT JOIN dbo.MD_Item I ON I.ItemNo COLLATE DATABASE_DEFAULT=R.ItemNo) S ON T.LotNo=S.LotNo
    WHEN MATCHED THEN UPDATE SET PartNo=S.ItemNo,PartName=S.ItemName,LocationNo=S.LocationNo,Qty=S.Qty,ReceivedAt=S.ReceivedAt,UpdatedAt=SYSDATETIME()
    WHEN NOT MATCHED THEN INSERT(LotNo,UnitType,PartNo,PartName,LocationNo,Qty,ReceivedAt,CreatedAt,UpdatedAt)
      VALUES(S.LotNo,'PART',S.ItemNo,S.ItemName,S.LocationNo,S.Qty,S.ReceivedAt,SYSDATETIME(),SYSDATETIME());
    IF @S='putaway' UPDATE dbo.WH_Inventory
      SET DeliveryNoteNo=CASE WHEN LotNo='5011LL260908850004' THEN 'PPT-WH-NOTE-PUTAWAY-RELOCATE' ELSE 'PPT-WH-NOTE-PUTAWAY' END,
          LocationNo=CASE WHEN LotNo='5011LL260908850004' THEN 'B0-10-A1' ELSE NULL END,UpdatedAt=SYSDATETIME()
      WHERE LotNo LIKE '5011LL26090885%';
    UPDATE L SET RemainingQty=R.Qty,CurrentLocationID=R.LocationNo,
      InventoryStatus=CASE WHEN @S='putaway' AND R.LocationNo IS NULL THEN 'RECEIVED' ELSE 'STORED' END,
      ModifiedBy='pda-ppt',ModifiedTS=SYSDATETIME()
    FROM dbo.tbl_Lot L JOIN @Rows R ON R.LotNo=L.LotCode COLLATE DATABASE_DEFAULT;
    IF @S='release' UPDATE dbo.WH_PickSlip SET PickedQty=0,Status='Open',CloseDate=NULL,CloseUserId=NULL,ModifiedBy='pda-ppt',ModifiedTS=SYSDATETIME() WHERE PickSlipNo='PS-PPT-WH-01';
    IF @S='history' INSERT dbo.WH_InventoryTransaction(TransactionTime,TransactionType,PartNo,LocationNo,LotNo,QtyBefore,QtyChange,QtyAfter,ReasonCode,SourceType,OperatorID,Note,CreatedBy,CreatedTS)
      SELECT DATEADD(second,V.OffsetSeconds,CONVERT(datetime2,CONVERT(date,SYSDATETIME()))),V.TransactionType,
        LEFT(R.ItemNo,20),LEFT(R.LocationNo,20),R.LotNo,V.QtyBefore,V.QtyChange,V.QtyAfter,V.ReasonCode,'PPT',N'SCTEST1',V.Note,N'pda-ppt',SYSDATETIME()
      FROM @Rows R
      CROSS JOIN (VALUES
        (1,'IN',CAST(0 AS decimal(18,3)),CAST(20 AS decimal(18,3)),CAST(20 AS decimal(18,3)),'INBOUND',N'PPT inbound 20 EA'),
        (2,'OUT',CAST(20 AS decimal(18,3)),CAST(-4 AS decimal(18,3)),CAST(16 AS decimal(18,3)),'PRODUCTION',N'PPT outbound 4 EA'),
        (3,'ADJ',CAST(16 AS decimal(18,3)),CAST(2 AS decimal(18,3)),CAST(18 AS decimal(18,3)),'COUNT_DIFF',N'PPT count correction +2 EA')
      ) V(OffsetSeconds,TransactionType,QtyBefore,QtyChange,QtyAfter,ReasonCode,Note);
    COMMIT TRANSACTION;
END;
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO
CREATE   PROCEDURE dbo.WH_PDA_RELEASE_PICK_LINES
    @PickSlipNo nvarchar(40)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Slip nvarchar(40) = UPPER(LTRIM(RTRIM(ISNULL(@PickSlipNo, N''))));
    DECLARE @PickSlipKey nvarchar(40);

    SELECT TOP (1)
        @PickSlipKey = COALESCE(NULLIF(RS.PickSlipNo, N''), CONCAT(N'RS-', RS.PickSlipID))
    FROM dbo.WH_PickSlip RS
    WHERE UPPER(COALESCE(NULLIF(RS.PickSlipNo, N''), CONCAT(N'RS-', RS.PickSlipID))) = @Slip
       OR UPPER(CONCAT(N'RS-', RS.PickSlipID)) = @Slip
       OR RS.PickSlipID = TRY_CONVERT(int, REPLACE(@Slip, N'RS-', N''))
    ORDER BY RS.PickSlipID;

    IF @PickSlipKey IS NULL
        RETURN;

    ;WITH RequiredParts AS
    (
        SELECT
            RS.PickSlipID,
            COALESCE(NULLIF(RS.PickSlipNo, N''), CONCAT(N'RS-', RS.PickSlipID)) AS PICK_SLIPNO,
            RS.ItemNo,
            COALESCE(I.ItemName, RS.ItemNo) AS ItemName,
            COALESCE(RS.DemandQty, 0) AS DemandQty,
            COALESCE(RS.PickedQty, 0) AS PickedQty,
            COALESCE(NULLIF(RS.ReqUserId, N''), RS.CreatedBy) AS RequestUserId
        FROM dbo.WH_PickSlip RS
        LEFT JOIN dbo.MD_Item I
               ON I.ItemNo = RS.ItemNo
        WHERE COALESCE(NULLIF(RS.PickSlipNo, N''), CONCAT(N'RS-', RS.PickSlipID)) = @PickSlipKey
    ),
    PickedPhysical AS
    (
        SELECT P.PickSlipID, SUM(COALESCE(P.PickedQty, 0)) AS PickedQty
        FROM dbo.WH_ReleasePicking P
        INNER JOIN RequiredParts R
                ON R.PickSlipID = P.PickSlipID
        GROUP BY P.PickSlipID
    ),
    RankedLocations AS
    (
        SELECT W.PartNo,W.LocationNo,
            ROW_NUMBER() OVER (PARTITION BY W.PartNo ORDER BY W.ReceivedAt,W.CreatedAt,W.LotNo) AS RN
        FROM dbo.WH_Inventory W
        INNER JOIN RequiredParts R ON R.ItemNo COLLATE DATABASE_DEFAULT=W.PartNo
        WHERE W.Qty>0 AND NULLIF(W.LocationNo,'') IS NOT NULL
    ),
    Locations AS
    (
        SELECT PartNo,
            MAX(CASE WHEN RN=1 THEN LocationNo END) AS LOC_01,
            MAX(CASE WHEN RN=2 THEN LocationNo END) AS LOC_02,
            MAX(CASE WHEN RN=3 THEN LocationNo END) AS LOC_03
        FROM RankedLocations WHERE RN<=3 GROUP BY PartNo
    )
    SELECT
        R.PICK_SLIPNO,
        R.ItemNo AS PARTNO,
        R.ItemName AS PARTNM,
        R.DemandQty AS REQ_BOX_QTY,
        R.PickedQty AS PICKED_BOX_QTY,
        COALESCE(P.PickedQty, 0) AS PICKED_QTY,
        R.RequestUserId AS REQ_USERID,
        L.LOC_01,L.LOC_02,L.LOC_03,
        CASE
            WHEN R.DemandQty > 0 AND R.PickedQty >= R.DemandQty THEN N'Picked'
            WHEN R.PickedQty > 0 THEN N'Partial'
            ELSE N'Open'
        END AS STATUS
    FROM RequiredParts R
    LEFT JOIN PickedPhysical P
           ON P.PickSlipID = R.PickSlipID
    LEFT JOIN Locations L ON L.PartNo=R.ItemNo COLLATE DATABASE_DEFAULT
    ORDER BY R.ItemNo;
END;
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO
CREATE   PROCEDURE dbo.WH_PDA_RELEASE_PICK_LOT
    @PickSlipNo nvarchar(40),
    @LotNo nvarchar(50),
    @UserId nvarchar(80),
    @TerminalId nvarchar(80)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @Slip nvarchar(40) = UPPER(LTRIM(RTRIM(ISNULL(@PickSlipNo, N''))));
    DECLARE @Lot nvarchar(50) = LTRIM(RTRIM(ISNULL(@LotNo, N'')));
    DECLARE @User nvarchar(80) = COALESCE(NULLIF(LTRIM(RTRIM(@UserId)), N''), N'PDA');
    DECLARE @Terminal nvarchar(80) = COALESCE(NULLIF(LTRIM(RTRIM(@TerminalId)), N''), N'PDA');
    DECLARE @PickSlipID int;
    DECLARE @PickSlipKey nvarchar(40);

    DECLARE @Validation table
    (
        PICK_SLIPNO nvarchar(40),
        LOTNO nvarchar(50),
        PARTNO varchar(50) NULL,
        PARTNM nvarchar(400) NULL,
        QTY decimal(18,3),
        UNIT varchar(10) NULL,
        LOCATION_NO varchar(50) NULL,
        LOCATION_NM nvarchar(100) NULL,
        ZONECD varchar(20) NULL,
        INV_STATUS varchar(20) NULL,
        PROD_DATE nvarchar(20) NULL,
        RCV_DATE nvarchar(20) NULL,
        IS_FIFO_SUGGESTED bit,
        IS_VALID bit,
        MESSAGE nvarchar(200)
    );

    INSERT INTO @Validation
    EXEC dbo.WH_PDA_RELEASE_SCAN_LOT @PickSlipNo = @Slip, @LotNo = @Lot;

    IF NOT EXISTS (SELECT 1 FROM @Validation WHERE IS_VALID = 1)
    BEGIN
        SELECT TOP (1) * FROM @Validation;
        RETURN;
    END;

    DECLARE
        @ItemNo varchar(50),
        @LocationID varchar(50),
        @Qty decimal(18,3),
        @InventoryQty decimal(18,3),
        @ResolvedLot nvarchar(50),
        @BeforeStatus varchar(20),
        @PickedTotal decimal(18,3),
        @DemandQty decimal(18,3);

    SELECT TOP (1)
        @ResolvedLot = LOTNO,
        @Qty = QTY
    FROM @Validation
    WHERE IS_VALID = 1;

    SELECT TOP (1)
        @ItemNo = W.PartNo,
        @LocationID = W.LocationNo,
        @InventoryQty = W.Qty,
        @BeforeStatus = CASE WHEN NULLIF(W.LocationNo,'') IS NULL THEN 'RECEIVED' ELSE 'STORED' END
    FROM dbo.WH_Inventory W WITH (UPDLOCK,HOLDLOCK)
    WHERE W.LotNo = @ResolvedLot
      AND W.PartNo = (SELECT TOP (1) PARTNO FROM @Validation)
      AND W.Qty > 0;

    IF COALESCE(@InventoryQty,0) <= 0
    BEGIN
        SELECT TOP (1)
            PICK_SLIPNO, LOTNO, PARTNO, PARTNM, QTY, UNIT, LOCATION_NO, LOCATION_NM,
            ZONECD, INV_STATUS, PROD_DATE, RCV_DATE, IS_FIFO_SUGGESTED,
            CAST(0 AS bit) AS IS_VALID,
            N'LOT status changed before picking. Scan again.' AS MESSAGE
        FROM @Validation;
        RETURN;
    END;

    SELECT TOP (1)
        @PickSlipKey = V.PICK_SLIPNO
    FROM @Validation V
    WHERE V.IS_VALID = 1;

    SELECT TOP (1)
        @PickSlipID = RS.PickSlipID
    FROM dbo.WH_PickSlip RS
    WHERE COALESCE(NULLIF(RS.PickSlipNo, N''), CONCAT(N'RS-', RS.PickSlipID)) = @PickSlipKey
      AND RS.ItemNo = @ItemNo
    ORDER BY RS.PickSlipID;

    IF @PickSlipID IS NULL
    BEGIN
        SELECT TOP (1)
            PICK_SLIPNO, LOTNO, PARTNO, PARTNM, QTY, UNIT, LOCATION_NO, LOCATION_NM,
            ZONECD, INV_STATUS, PROD_DATE, RCV_DATE, IS_FIFO_SUGGESTED,
            CAST(0 AS bit) AS IS_VALID,
            N'Pick Slip line was not found for this LOT.' AS MESSAGE
        FROM @Validation;
        RETURN;
    END;

    BEGIN TRANSACTION;

    UPDATE dbo.WH_Inventory
       SET Qty = 0,UpdatedAt = SYSDATETIME()
     WHERE LotNo = @ResolvedLot AND Qty = @InventoryQty;
    IF @@ROWCOUNT<>1 THROW 51620, 'LOT inventory changed before Release.', 1;

    INSERT INTO dbo.WH_ReleasePicking
    (
        PickingNo, PickSlipID, ItemNo, LocationID, LotID, PickedQty,
        PickedAt, PickedBy, TerminalID, FifoOverride, CreatedBy, CreatedTS
    )
    VALUES
    (
        CONCAT('PICK-', FORMAT(SYSDATETIME(), 'yyMMddHHmmssfff')),
        @PickSlipID, @ItemNo, @LocationID, NULL, @Qty,
        SYSDATETIME(), @User, @Terminal, 0, LEFT(@User,20), SYSDATETIME()
    );

    UPDATE dbo.WH_PickSlip
       SET PickedQty = COALESCE(PickedQty, 0) + 1,
            Status = CASE
                WHEN COALESCE(PickedQty, 0) + 1 >= COALESCE(DemandQty, 0) THEN 'Picked'
               ELSE 'Partial'
           END,
           ModifiedBy = @User,
           ModifiedTS = SYSDATETIME()
     WHERE PickSlipID = @PickSlipID;

    SELECT
        @PickedTotal = COALESCE(PickedQty, 0),
        @DemandQty = COALESCE(DemandQty, 0)
    FROM dbo.WH_PickSlip
    WHERE PickSlipID = @PickSlipID;

    INSERT INTO dbo.WH_InventoryTransaction
    (
        TransactionTime, TransactionType, PartNo, LocationNo, LotNo, QtyBefore, QtyChange, QtyAfter,
        ReasonCode, SourceType, SourceID, OperatorID, Note, CreatedBy, CreatedTS
    )
    VALUES
    (
        SYSDATETIME(), 'OUT', @ItemNo, @LocationID, @ResolvedLot, @InventoryQty, -@InventoryQty, 0,
        'RELEASE_PICK', 'PICK_SLIP', @PickSlipID, @User,
        CONCAT('PDA release pick ', @PickSlipKey), LEFT(@User,20), SYSDATETIME()
    );

    COMMIT TRANSACTION;

    SELECT TOP (1)
        PICK_SLIPNO,
        LOTNO,
        PARTNO,
        PARTNM,
        QTY,
        UNIT,
        LOCATION_NO,
        LOCATION_NM,
        ZONECD,
        'Released' AS INV_STATUS,
        PROD_DATE,
        RCV_DATE,
        CAST(1 AS bit) AS IS_FIFO_SUGGESTED,
        CAST(1 AS bit) AS IS_VALID,
        N'Release pick completed.' AS MESSAGE
    FROM @Validation;
END;
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE dbo.WH_PDA_RELEASE_SCAN_LOT @PickSlipNo nvarchar(40),@LotNo nvarchar(50)
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Slip nvarchar(40)=UPPER(LTRIM(RTRIM(ISNULL(@PickSlipNo,N''))));
    DECLARE @Lot nvarchar(50)=LTRIM(RTRIM(ISNULL(@LotNo,N'')));
    DECLARE @Item varchar(50),@Name nvarchar(400),@Location varchar(50),@Qty decimal(18,3),@Received datetime2,@Oldest nvarchar(100);
    SELECT @Item=W.PartNo,@Name=COALESCE(NULLIF(W.PartName,N''),I.ItemName COLLATE DATABASE_DEFAULT),@Location=W.LocationNo,@Qty=W.Qty,@Received=W.ReceivedAt
    FROM dbo.WH_Inventory W
    LEFT JOIN dbo.MD_Item I
      ON I.ItemNo COLLATE DATABASE_DEFAULT = W.PartNo COLLATE DATABASE_DEFAULT
    WHERE UPPER(W.LotNo)=UPPER(@Lot);
    IF @Item IS NULL
    BEGIN SELECT @Slip PICK_SLIPNO,@Lot LOTNO,NULL PARTNO,NULL PARTNM,CAST(0 AS decimal(18,3)) QTY,NULL UNIT,NULL LOCATION_NO,NULL LOCATION_NM,NULL ZONECD,NULL INV_STATUS,NULL PROD_DATE,NULL RCV_DATE,CAST(0 AS bit) IS_FIFO_SUGGESTED,CAST(0 AS bit) IS_VALID,N'LOT was not found.' MESSAGE; RETURN; END;
    IF COALESCE(@Qty,0)<=0
    BEGIN SELECT @Slip PICK_SLIPNO,@Lot LOTNO,@Item PARTNO,@Name PARTNM,@Qty QTY,I.DefaultUOM UNIT,@Location LOCATION_NO,L.LocationName LOCATION_NM,L.ZoneCode ZONECD,N'RELEASED' INV_STATUS,NULL PROD_DATE,CONVERT(nvarchar(20),@Received,23) RCV_DATE,CAST(0 AS bit) IS_FIFO_SUGGESTED,CAST(0 AS bit) IS_VALID,N'LOT is not available for release.' MESSAGE FROM dbo.MD_Item I LEFT JOIN dbo.MD_Location L ON L.LocationID=@Location WHERE I.ItemNo=@Item; RETURN; END;
    IF NOT EXISTS(SELECT 1 FROM dbo.WH_PickSlip WHERE UPPER(COALESCE(NULLIF(PickSlipNo,N''),CONCAT(N'RS-',PickSlipID)))=@Slip AND ItemNo=@Item AND UPPER(COALESCE(Status,'OPEN')) NOT IN('CLOSED','RELEASED','CANCELED','CANCELLED'))
    BEGIN SELECT @Slip PICK_SLIPNO,@Lot LOTNO,@Item PARTNO,@Name PARTNM,@Qty QTY,I.DefaultUOM UNIT,@Location LOCATION_NO,L.LocationName LOCATION_NM,L.ZoneCode ZONECD,N'STORED' INV_STATUS,NULL PROD_DATE,CONVERT(nvarchar(20),@Received,23) RCV_DATE,CAST(0 AS bit) IS_FIFO_SUGGESTED,CAST(0 AS bit) IS_VALID,N'Wrong item. This LOT is not requested by the selected Pick Slip.' MESSAGE FROM dbo.MD_Item I LEFT JOIN dbo.MD_Location L ON L.LocationID=@Location WHERE I.ItemNo=@Item; RETURN; END;
    SELECT TOP(1) @Oldest=LotNo FROM dbo.WH_Inventory WHERE PartNo=@Item AND Qty>0 ORDER BY ReceivedAt,LotNo;
    SELECT @Slip PICK_SLIPNO,@Lot LOTNO,@Item PARTNO,@Name PARTNM,@Qty QTY,I.DefaultUOM UNIT,@Location LOCATION_NO,L.LocationName LOCATION_NM,L.ZoneCode ZONECD,N'STORED' INV_STATUS,NULL PROD_DATE,CONVERT(nvarchar(20),@Received,23) RCV_DATE,
      CONVERT(bit,CASE WHEN UPPER(@Oldest)=UPPER(@Lot) THEN 1 ELSE 0 END) IS_FIFO_SUGGESTED,
      CONVERT(bit,CASE WHEN UPPER(@Oldest)=UPPER(@Lot) THEN 1 ELSE 0 END) IS_VALID,
      CASE WHEN UPPER(@Oldest)=UPPER(@Lot) THEN N'LOT is ready to pick.' ELSE CONCAT(N'FIFO violation. Pick LOT ',@Oldest,N' first.') END MESSAGE
    FROM dbo.MD_Item I LEFT JOIN dbo.MD_Location L ON L.LocationID=@Location WHERE I.ItemNo=@Item;
END;
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO
CREATE   PROCEDURE dbo.WH_PDA_RELEASE_SLIP_STATUS
    @PickSlipNo nvarchar(40)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Slip nvarchar(40) = UPPER(LTRIM(RTRIM(ISNULL(@PickSlipNo, N''))));
    DECLARE @PickSlipID int;

    IF @Slip = N''
    BEGIN
        SELECT
            @Slip AS PICK_SLIPNO,
            CAST(0 AS bit) AS EXISTS_FLAG,
            CAST(0 AS bit) AS IS_CLOSED,
            CAST(0 AS int) AS LINE_COUNT,
            CAST(NULL AS nvarchar(40)) AS REQ_LOCATION,
            CAST(NULL AS date) AS REQ_DATE,
            CAST(NULL AS datetime2) AS CLOSE_DATE,
            N'Pick Slip No is required.' AS MESSAGE;
        RETURN;
    END;

    SELECT TOP (1)
        @PickSlipID = RS.PickSlipID
    FROM dbo.WH_PickSlip RS
    WHERE UPPER(COALESCE(NULLIF(RS.PickSlipNo, N''), CONCAT(N'RS-', RS.PickSlipID))) = @Slip
       OR UPPER(CONCAT(N'RS-', RS.PickSlipID)) = @Slip
       OR RS.PickSlipID = TRY_CONVERT(int, REPLACE(@Slip, N'RS-', N''))
    ORDER BY RS.PickSlipID;

    IF @PickSlipID IS NULL
    BEGIN
        SELECT
            @Slip AS PICK_SLIPNO,
            CAST(0 AS bit) AS EXISTS_FLAG,
            CAST(0 AS bit) AS IS_CLOSED,
            CAST(0 AS int) AS LINE_COUNT,
            CAST(NULL AS nvarchar(40)) AS REQ_LOCATION,
            CAST(NULL AS date) AS REQ_DATE,
            CAST(NULL AS datetime2) AS CLOSE_DATE,
            N'Pick Slip was not found.' AS MESSAGE;
        RETURN;
    END;

    SELECT
        COALESCE(NULLIF(RS.PickSlipNo, N''), CONCAT(N'RS-', RS.PickSlipID)) AS PICK_SLIPNO,
        CAST(1 AS bit) AS EXISTS_FLAG,
        CASE WHEN UPPER(COALESCE(RS.Status, N'')) IN (N'CLOSED', N'RELEASED', N'PICKED', N'CANCELED', N'CANCELLED')
                  OR RS.CloseDate IS NOT NULL THEN CAST(1 AS bit) ELSE CAST(0 AS bit) END AS IS_CLOSED,
        (
            SELECT COUNT(*)
            FROM dbo.WH_PickSlip L
            WHERE COALESCE(NULLIF(L.PickSlipNo, N''), CONCAT(N'RS-', L.PickSlipID))
                = COALESCE(NULLIF(RS.PickSlipNo, N''), CONCAT(N'RS-', RS.PickSlipID))
        ) AS LINE_COUNT,
        RS.ReqLocation AS REQ_LOCATION,
        CONVERT(date, RS.RequiredAt) AS REQ_DATE,
        RS.CloseDate AS CLOSE_DATE,
        CASE
            WHEN UPPER(COALESCE(RS.Status, N'')) IN (N'CLOSED', N'RELEASED', N'PICKED', N'CANCELED', N'CANCELLED')
                 OR RS.CloseDate IS NOT NULL THEN N'This Pick Slip has already been processed.'
            ELSE N'Pick Slip is ready.'
        END AS MESSAGE
    FROM dbo.WH_PickSlip RS
    WHERE RS.PickSlipID = @PickSlipID;
END;
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO

-- =====================================================================
--  Schedule / Inbound
--  Source: dbo.WH_PurchaseOrder
-- =====================================================================
CREATE   PROCEDURE dbo.WH_PDA_SCHEDULE_INBOUND_LIST
    @CompanyCode nvarchar(10) = N'1000',
    @BusinessCode nvarchar(10) = N'5011',
    @ScheduleYear nvarchar(4),
    @ScheduleQuarter nvarchar(2),
    @SupplierCode nvarchar(10) = NULL,
    @LanguageCode nvarchar(10) = N'EN'
AS
BEGIN
    SET NOCOUNT ON;

    SELECT TOP (100)
        P.PoNumber AS PurchaseOrderNo,
        P.PoLineNo AS PurchaseOrderLineNo,
        COALESCE(V.VendorName, P.VendorID) AS SupplierName,
        P.ItemNo AS MaterialNo,
        I.ItemName AS MaterialName,
        I.CarType AS CarCode,
        COALESCE(P.UnitCode, I.DefaultUOM) AS UnitOfMeasure,
        COALESCE(P.OrderQty, 0) AS PurchaseOrderQty,
        COALESCE(P.ReceivedQty, 0) AS ReceivedQty,
        CASE
            WHEN COALESCE(P.OrderQty, 0) - COALESCE(P.ReceivedQty, 0) < 0 THEN 0
            ELSE COALESCE(P.OrderQty, 0) - COALESCE(P.ReceivedQty, 0)
        END AS RemainingQty,
        P.DueDate AS ExpectedArrivalDate,
        P.OrderDate AS PurchaseOrderCreatedDate,
        CASE
            WHEN COALESCE(P.OrderQty, 0) - COALESCE(P.ReceivedQty, 0) <= 0 THEN N'Complete'
            WHEN P.DueDate < CONVERT(date, GETDATE()) THEN N'Late'
            ELSE N'In Progress'
        END AS ReceiptStatus
    FROM dbo.WH_PurchaseOrder P
    LEFT JOIN dbo.MD_Item I
           ON I.ItemNo = P.ItemNo
    LEFT JOIN dbo.MD_Vendor V
           ON V.VendorID = P.VendorID
    WHERE (@SupplierCode IS NULL OR P.VendorID = @SupplierCode)
      AND (
            P.DueDate IS NULL
            OR (
                YEAR(P.DueDate) = TRY_CONVERT(int, @ScheduleYear)
                AND DATEPART(quarter, P.DueDate) = TRY_CONVERT(int, @ScheduleQuarter)
            )
      )
    ORDER BY P.DueDate, P.PoNumber, P.PoLineNo;
END;
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO

-- =====================================================================
--  Schedule / Release
--  Source: PP-007 WO Release / dbo.PP_WorkOrder
-- =====================================================================
CREATE   PROCEDURE dbo.WH_PDA_SCHEDULE_RELEASE_LIST
    @DueDateFrom date = NULL,
    @DueDateTo date = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SELECT TOP (100)
        W.WoID AS WorkOrderId,
        W.WoNumber AS WorkOrderNo,
        W.ItemNo AS PartNo,
        I.ItemName AS PartName,
        COALESCE(W.OrderQty, 0) AS OrderQty,
        COALESCE(I.DefaultUOM, N'EA') AS Unit,
        W.DueDate,
        COALESCE(W.Status, N'Released') AS WorkOrderStatus,
        W.ReleasedAt,
        W.LineID
    FROM dbo.PP_WorkOrder W
    LEFT JOIN dbo.MD_Item I ON I.ItemNo = W.ItemNo
    WHERE W.Status IN (N'Released', N'In Progress')
      AND (@DueDateFrom IS NULL OR W.DueDate >= @DueDateFrom)
      AND (@DueDateTo IS NULL OR W.DueDate <= @DueDateTo)
    ORDER BY ISNULL(W.DueDate, CONVERT(date, '9999-12-31')),
             ISNULL(W.Priority, 5),
             W.WoID;
END;
GO
